    const BuffRuleDefinition *FindBuffRule(std::string_view guid) {
        const auto found = std::lower_bound(g_BuffRules.begin(), g_BuffRules.end(), guid, [](const BuffRuleDefinition &row, std::string_view value) { return row.guid < value; });
        return found != g_BuffRules.end() && found->guid == guid ? &*found : FindCustomBuffRule(guid);
    }
